<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import{useRouter}from'vue-router';import{monthlyContractApi}from'../api';import type{ContractCustomer,ContractInput,ContractOptions,MonthlyContract}from'../types'
const props=defineProps<{contractId?:number;renewalFromId?:number}>(),router=useRouter(),options=ref<ContractOptions|null>(null),loading=ref(false),saving=ref(false),error=ref(''),errors=ref<Record<string,string[]>>({})
const form=reactive<ContractInput>({customer_id:null,customer_name:'',guest_name:'',contact_person:'',customer_phone:'',customer_email:'',customer_address:'',assignment_type:'Vehicle Only',car_id:null,driver_id:null,operator_id:null,operator_name:'',even_odd:'',operation_sheet:'',start_date:'',end_date:'',monthly_rate:'0',rental_currency:'MMK',rental_status:'Including fuel',status:'Active',note:'',prepared_by:'',invoice_sender:'',checked_by:'',off_day:'',service_hour:'',insurance_price:'0',insurance_company:'',terms_conditions:''})
const selectedCustomer=computed(()=>options.value?.customers.find(c=>c.id===form.customer_id))
const showCar=computed(()=>form.assignment_type!=='Driver Only'),showDriver=computed(()=>form.assignment_type==='Vehicle and Driver'||form.assignment_type==='Driver Only'),requiresDriver=computed(()=>form.assignment_type==='Vehicle and Driver')
function setCustomer(c:ContractCustomer|undefined){if(!c)return;form.customer_name=c.company_name||c.guest_name||'';form.guest_name=c.guest_name||'';form.contact_person=c.contact_person||'';form.customer_phone=c.contact_phone||'';form.customer_email=c.contact_email||'';form.customer_address=c.customer_address||'';if(!form.off_day)form.off_day=c.off_day||'';if(!form.service_hour)form.service_hour=c.service_hour||''}
function assign(c:MonthlyContract){Object.assign(form,{customer_id:c.customer_id,customer_name:c.customer_name,guest_name:c.guest_name||'',contact_person:c.contact_person||'',customer_phone:c.customer_phone||'',customer_email:c.customer_email||'',customer_address:c.customer_address||'',assignment_type:c.assignment_type,car_id:c.car_id,driver_id:c.driver_id,operator_id:c.operator_id,operator_name:c.operator_name||'',even_odd:c.even_odd||'',operation_sheet:c.operation_sheet||'',start_date:c.start_date,end_date:c.end_date,monthly_rate:c.monthly_rate.replace(/\.00$/,''),rental_currency:c.rental_currency,rental_status:c.rental_status,status:c.status==='Renewed'?'Active':c.status,note:c.note||'',prepared_by:c.prepared_by||'',invoice_sender:c.invoice_sender||'',checked_by:c.checked_by||'',off_day:c.off_day||'',service_hour:c.service_hour||'',insurance_price:c.insurance_price.replace(/\.00$/,''),insurance_company:c.insurance_company||'',terms_conditions:c.terms_conditions||''})}
function addDay(s:string){const[y=0,m=1,d=0]=s.split('-').map(Number);const date=new Date(Date.UTC(y,m-1,d+1));return`${date.getUTCFullYear()}-${String(date.getUTCMonth()+1).padStart(2,'0')}-${String(date.getUTCDate()).padStart(2,'0')}`}
function monthMinusDay(s:string){const[y=0,m=1,d=1]=s.split('-').map(Number);const date=new Date(Date.UTC(y,m-1,d));date.setUTCMonth(date.getUTCMonth()+1);date.setUTCDate(date.getUTCDate()-1);return`${date.getUTCFullYear()}-${String(date.getUTCMonth()+1).padStart(2,'0')}-${String(date.getUTCDate()).padStart(2,'0')}`}
onMounted(async()=>{loading.value=true;try{options.value=await monthlyContractApi.options();if(props.contractId||props.renewalFromId){const old=await monthlyContractApi.get(props.contractId||props.renewalFromId!);assign(old);if(props.renewalFromId){form.start_date=addDay(old.end_date);form.end_date=monthMinusDay(form.start_date);form.status='Active'}}else{const today=new Date(),start=`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(today.getDate()).padStart(2,'0')}`;form.start_date=start;form.end_date=monthMinusDay(start)}}catch(e:any){error.value=e?.response?.data?.message||'Unable to load contract information.'}finally{loading.value=false}})
async function submit(){saving.value=true;error.value='';errors.value={};try{const saved=props.renewalFromId?await monthlyContractApi.renew(props.renewalFromId,form):await monthlyContractApi.save(form,props.contractId);await router.push(`/monthly-contracts/${saved.id}`)}catch(e:any){error.value=e?.response?.data?.message||'Unable to save contract.';errors.value=e?.response?.data?.errors||{}}finally{saving.value=false}}
</script>
<template><div v-if="loading" class="alert alert-light border">Loading contract form…</div><div v-else><div v-if="error" class="alert alert-danger" role="alert">{{error}}</div><div v-if="renewalFromId" class="alert alert-info">Renewal dates and contract number are generated on the server from the previous contract period.</div><form class="card shadow-sm" @submit.prevent="submit"><div class="card-body"><div class="row g-3">
<div class="col-md-6"><label class="form-label" for="mc-customer">Customer</label><select id="mc-customer" v-model="form.customer_id" class="form-select" required @change="setCustomer(selectedCustomer)"><option :value="null">Choose customer</option><option v-for="c in options?.customers||[]" :key="c.id" :value="c.id">{{c.company_name||c.guest_name}} · {{c.customer_status}}</option></select><div v-if="errors.customer_id" class="text-danger small">{{errors.customer_id[0]}}</div></div><div class="col-md-6"><label class="form-label" for="mc-customer-name">Contract customer name</label><input id="mc-customer-name" v-model="form.customer_name" class="form-control" required><div v-if="errors.customer_name" class="text-danger small">{{errors.customer_name[0]}}</div></div>
<div class="col-md-6"><label class="form-label" for="mc-assignment">Assignment type</label><select id="mc-assignment" v-model="form.assignment_type" class="form-select"><option>Vehicle Only</option><option>Driver Only</option><option>Vehicle and Driver</option></select></div><div v-if="showCar" class="col-md-6"><label class="form-label" for="mc-car">Monthly fleet vehicle</label><select id="mc-car" v-model="form.car_id" class="form-select" :required="showCar"><option :value="null">Choose vehicle</option><option v-for="v in options?.cars||[]" :key="v.id" :value="v.id" :disabled="['Maintenance','Inactive'].includes(v.availability_status)">{{v.plate_no}} · {{v.model_name}} ({{v.availability_status}})</option></select><div v-if="errors.car_id" class="text-danger small">{{errors.car_id[0]}}</div></div><div v-if="showDriver" class="col-md-6"><label class="form-label" for="mc-driver">Monthly fleet driver</label><select id="mc-driver" v-model="form.driver_id" class="form-select" :required="requiresDriver"><option :value="null">Choose driver</option><option v-for="d in options?.drivers||[]" :key="d.id" :value="d.id" :disabled="['Leave','Inactive'].includes(d.driver_status)">{{d.full_name}} ({{d.driver_status}})</option></select><div v-if="errors.driver_id" class="text-danger small">{{errors.driver_id[0]}}</div></div>
<div class="col-md-6"><label class="form-label" for="mc-operator">Operator</label><select id="mc-operator" v-model="form.operator_id" class="form-select"><option :value="null">No operator</option><option v-for="o in options?.operators||[]" :key="o.id" :value="o.id">{{o.full_name}} ({{o.operator_status}})</option></select></div><div class="col-md-3"><label class="form-label" for="mc-start">Start date</label><input id="mc-start" v-model="form.start_date" class="form-control" type="date" required><div v-if="errors.start_date" class="text-danger small">{{errors.start_date[0]}}</div></div><div class="col-md-3"><label class="form-label" for="mc-end">End date</label><input id="mc-end" v-model="form.end_date" class="form-control" type="date" required><div v-if="errors.end_date" class="text-danger small">{{errors.end_date[0]}}</div></div>
<div class="col-md-3"><label class="form-label" for="mc-rate">Monthly rate</label><input id="mc-rate" v-model="form.monthly_rate" class="form-control" inputmode="numeric" required><div v-if="errors.monthly_rate" class="text-danger small">{{errors.monthly_rate[0]}}</div></div><div class="col-md-3"><label class="form-label" for="mc-currency">Currency</label><select id="mc-currency" v-model="form.rental_currency" class="form-select"><option>MMK</option><option>USD</option></select></div><div class="col-md-3"><label class="form-label" for="mc-rental-status">Rental status</label><select id="mc-rental-status" v-model="form.rental_status" class="form-select"><option>Including fuel</option><option>Excluding fuel</option><option>Car only</option><option>Driver only</option></select></div><div class="col-md-3"><label class="form-label" for="mc-status">Contract status</label><select id="mc-status" v-model="form.status" class="form-select"><option v-for="s in options?.statuses||[]" :key="s">{{s}}</option></select></div>
<div class="col-md-3"><label class="form-label" for="mc-insurance-price">Contract insurance price</label><input id="mc-insurance-price" v-model="form.insurance_price" class="form-control" inputmode="numeric"><div v-if="errors.insurance_price" class="text-danger small">{{errors.insurance_price[0]}}</div></div><div class="col-md-9"><label class="form-label" for="mc-insurance-company">Contract insurance company snapshot</label><input id="mc-insurance-company" v-model="form.insurance_company" class="form-control"></div>
<div class="col-md-4"><label class="form-label" for="mc-guest">Guest name</label><input id="mc-guest" v-model="form.guest_name" class="form-control"></div><div class="col-md-4"><label class="form-label" for="mc-contact">Contact person</label><input id="mc-contact" v-model="form.contact_person" class="form-control"></div><div class="col-md-4"><label class="form-label" for="mc-phone">Phone</label><input id="mc-phone" v-model="form.customer_phone" class="form-control"></div><div class="col-md-6"><label class="form-label" for="mc-email">Email</label><input id="mc-email" v-model="form.customer_email" class="form-control" type="email"></div><div class="col-md-6"><label class="form-label" for="mc-address">Address</label><input id="mc-address" v-model="form.customer_address" class="form-control"></div>
<div class="col-md-3"><label class="form-label" for="mc-evenodd">Even / odd</label><select id="mc-evenodd" v-model="form.even_odd" class="form-select"><option value="">Not set</option><option>Even</option><option>Odd</option></select></div><div class="col-md-3"><label class="form-label" for="mc-offday">Off day</label><input id="mc-offday" v-model="form.off_day" class="form-control"></div><div class="col-md-3"><label class="form-label" for="mc-service-hour">Service hours</label><input id="mc-service-hour" v-model="form.service_hour" class="form-control"></div><div class="col-md-3"><label class="form-label" for="mc-sheet">Operation sheet</label><input id="mc-sheet" v-model="form.operation_sheet" class="form-control"></div>
<div class="col-md-4"><label class="form-label" for="mc-prepared">Prepared by</label><input id="mc-prepared" v-model="form.prepared_by" class="form-control"></div><div class="col-md-4"><label class="form-label" for="mc-sender">Invoice sender</label><input id="mc-sender" v-model="form.invoice_sender" class="form-control"></div><div class="col-md-4"><label class="form-label" for="mc-checked">Checked by</label><input id="mc-checked" v-model="form.checked_by" class="form-control"></div><div class="col-12"><label class="form-label" for="mc-terms">Terms and conditions</label><textarea id="mc-terms" v-model="form.terms_conditions" class="form-control" rows="3"/></div><div class="col-12"><label class="form-label" for="mc-note">Notes</label><textarea id="mc-note" v-model="form.note" class="form-control" rows="2"/></div>
</div></div><div class="card-footer bg-white d-flex justify-content-end gap-2"><RouterLink to="/monthly-contracts" class="btn btn-outline-secondary">Cancel</RouterLink><button class="btn btn-primary" :disabled="saving">{{saving?'Saving…':'Save contract'}}</button></div></form></div></template>
